head.script:
scwin.tabControl1_ontabclick = function(tabID, idx) {
    alert("tab-event발생");
};
scwin.trigger2_onclick = function(e) {
    grd.setDisabled("grid", true);
    //alert("grid-disabled");
    log = "grid-disabled";
};
scwin.trigger1_onclick = function(e) {
    tabControl1.disableTab(0);
    //alert("tab-disabled");
    log1 = "tab-disabled";
};
scwin.clickCheck = function(id) {
    if (!WebSquare.wUnit.getJq(id).hasClass("w2grid_default_disabled")) {
        grd_cell_0_0.childNodes[0].click()
    }
}
scwin.checkVal = function(){
	return WebSquare.wUnit.getDomById('grd_cell_0_0').querySelector('input').getAttribute('checked') == '';
}

scwin.unitTest = function() {
    //Unit test
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");

    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger2').click()");
    WebSquare.wUnit.addCommand("pause", "500");

    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('grd_cell_0_0').querySelector('input').click()");
    WebSquare.wUnit.addCommand("pause", "500");

	WebSquare.wUnit.addCommand("assert", "scwin.checkVal()", "true");
	WebSquare.wUnit.addCommand("pause", "500");

	//WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getJq('#grd_cell_0_0.childNodes[0]').simulate('click')");
    //WebSquare.wUnit.addCommand("pause", "500");

    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger1').click()");
    WebSquare.wUnit.addCommand("pause", "500");

    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('grd_cell_0_0').querySelector('input').click()");
    WebSquare.wUnit.addCommand("pause", "500");

	WebSquare.wUnit.addCommand("assert", "scwin.checkVal()", "true");
	WebSquare.wUnit.addCommand("pause", "500");


    //Run and Stop test
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.unitTest();

scwin.onpageload = function() {
    var log, log1;
    //Function unitTest
    //Create buy Truong.Luu
    //Create date 27-Feb-2018
    //End unitTest
}
